using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace SoundDesk;

/// <summary>Per-song stage colors generated by an OpenAI-compatible chat endpoint, matching the Mac mood service.</summary>
public sealed class DesktopMoodService
{
    public static DesktopMoodService Shared { get; } = new();

    public static readonly string[] ColorKeys =
    [
        "atmosphere", "volumetricBeam", "topLightArray", "laserFanBlue", "laserFanGreen",
        "rotatingBeam", "rotatingBeamExtra", "edgeLight", "coronaFilaments", "pulseRing"
    ];

    private static readonly float[] DefaultColors =
    [
        1.0f, 0.88f, 0.72f, 1, 1.0f, 0.85f, 0.65f, 1, 0.3f, 0.6f, 1.0f, 1, 0.25f, 0.55f, 1.0f, 1,
        0.35f, 1.0f, 0.45f, 1, 1.0f, 0.4f, 0.8f, 1, 1.0f, 0.5f, 0.9f, 1, 1.0f, 0.75f, 0.35f, 1,
        0.9f, 0.6f, 0.8f, 1, 0.8f, 0.3f, 1.0f, 1
    ];

    private static readonly HttpClient Http = new() { Timeout = TimeSpan.FromSeconds(25) };
    private static readonly string DataDirectory = Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "SoundDesk");
    private readonly string _settingsPath = Path.Combine(DataDirectory, "mood-settings.json");
    private readonly string _cachePath = Path.Combine(DataDirectory, "mood-colors.json");
    private readonly PlatformCredentialStore _secrets = new();
    private Dictionary<string, float[]> _cache = new(StringComparer.Ordinal);
    private int _generation;

    /// <summary>Ten RGBA colors in <see cref="ColorKeys"/> order.</summary>
    public float[] Colors { get; private set; } = (float[])DefaultColors.Clone();
    public string BaseUrl { get; private set; } = "https://api.deepseek.com";
    public string Model { get; private set; } = "deepseek-chat";
    public string ApiKey => _secrets.Load("DesktopMood.apiKey") ?? "";

    private DesktopMoodService()
    {
        try
        {
            if (File.Exists(_settingsPath))
            {
                var saved = JsonNode.Parse(File.ReadAllText(_settingsPath));
                BaseUrl = saved?["baseUrl"]?.GetValue<string>() ?? BaseUrl;
                Model = saved?["model"]?.GetValue<string>() ?? Model;
            }
            if (File.Exists(_cachePath))
                _cache = JsonSerializer.Deserialize<Dictionary<string, float[]>>(File.ReadAllText(_cachePath)) ?? _cache;
        }
        catch (Exception error) when (error is IOException or JsonException or InvalidOperationException) { }
    }

    public void Configure(string baseUrl, string model, string apiKey)
    {
        BaseUrl = baseUrl.Trim();
        Model = model.Trim();
        Directory.CreateDirectory(DataDirectory);
        File.WriteAllText(_settingsPath, new JsonObject { ["baseUrl"] = BaseUrl, ["model"] = Model }.ToJsonString());
        if (string.IsNullOrWhiteSpace(apiKey)) _secrets.Delete("DesktopMood.apiKey");
        else _secrets.Save("DesktopMood.apiKey", apiKey.Trim());
    }

    public async void Analyze(string title, string? artist)
    {
        var generation = ++_generation;
        Colors = (float[])DefaultColors.Clone();
        var apiKey = ApiKey;
        if (apiKey.Length == 0) return;
        var cacheKey = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes($"{Model}|{title}|{artist ?? ""}"))).ToLowerInvariant();
        if (_cache.TryGetValue(cacheKey, out var cached) && cached.Length == DefaultColors.Length)
        {
            Colors = cached;
            return;
        }
        if (!Uri.TryCreate(BaseUrl, UriKind.Absolute, out var baseUri) || baseUri.Scheme != Uri.UriSchemeHttps) return;
        var builder = new UriBuilder(baseUri);
        if (builder.Path is "" or "/" or "/v1" or "/v1/") builder.Path = "/v1/chat/completions";
        var artistText = string.IsNullOrWhiteSpace(artist) ? "" : $" - {artist}";
        var prompt = $"请为歌曲《{title}》{artistText}设计情绪氛围光。只返回 JSON 对象，包含 colors 对象，字段 atmosphere、volumetricBeam、topLightArray、laserFanBlue、laserFanGreen、rotatingBeam、rotatingBeamExtra、edgeLight、coronaFilaments、pulseRing；每个字段为 0 到 1 的 RGB 三元素数组。让颜色贴合歌曲情绪，主色与鼓点强调色有清楚区别。laserFanBlue 是字段名而非固定蓝色限制：请按歌曲情绪选择有明显辨识度的高饱和色相，可以是青、紫、洋红、红橙或其他颜色，不要每首歌都返回相近的蓝色。深空蜂巢的吉他颜色波依次使用 pulseRing、coronaFilaments、volumetricBeam、rotatingBeam；请让这四种颜色形成符合歌曲情绪的色组，彼此有清晰区分，并避免所有歌曲都落在同一组紫/蓝色。";
        var payload = new JsonObject
        {
            ["model"] = Model,
            ["messages"] = new JsonArray(
                new JsonObject { ["role"] = "system", ["content"] = "你是音乐舞台灯光设计师。只输出有效 JSON。" },
                new JsonObject { ["role"] = "user", ["content"] = prompt }),
            ["temperature"] = 0.7,
            ["max_tokens"] = 600
        };
        try
        {
            using var request = new HttpRequestMessage(HttpMethod.Post, builder.Uri)
            {
                Content = new StringContent(payload.ToJsonString(), Encoding.UTF8, "application/json")
            };
            request.Headers.TryAddWithoutValidation("Authorization", $"Bearer {apiKey}");
            using var response = await Http.SendAsync(request);
            if (!response.IsSuccessStatusCode)
            {
                WallpaperDiagnostics.Write($"Mood colors unavailable: HTTP {(int)response.StatusCode}");
                return;
            }
            var content = JsonNode.Parse(await response.Content.ReadAsStringAsync())?["choices"]?[0]?["message"]?["content"]?.GetValue<string>() ?? "";
            var start = content.IndexOf('{');
            var end = content.LastIndexOf('}');
            if (start < 0 || end <= start) return;
            var colors = JsonNode.Parse(content[start..(end + 1)])?["colors"]?.AsObject();
            if (colors is null || generation != _generation) return;
            var parsed = (float[])DefaultColors.Clone();
            for (var index = 0; index < ColorKeys.Length; index++)
            {
                if (colors[ColorKeys[index]] is not JsonArray rgb || rgb.Count != 3) continue;
                for (var channel = 0; channel < 3; channel++)
                    parsed[index * 4 + channel] = Math.Clamp((float)(rgb[channel]?.GetValue<double>() ?? 0), 0, 1);
            }
            Colors = parsed;
            _cache[cacheKey] = parsed;
            Directory.CreateDirectory(DataDirectory);
            File.WriteAllText(_cachePath, JsonSerializer.Serialize(_cache));
        }
        catch (Exception error) when (error is HttpRequestException or TaskCanceledException or JsonException
            or InvalidOperationException or IOException or FormatException)
        {
            WallpaperDiagnostics.Write($"Mood colors request failed: {error.Message}");
        }
    }
}
